#include <queue>
#include <vector>
#include <iostream>

// Create a custom comparator (Min-Heap)
struct CustomCompare {
    bool operator()(int a, int b) const { return a > b; }
};

int main() {
    // 1. Min-Heap using std::greater
    std::priority_queue<int, std::vector<int>, std::greater<int>> min_pq;
    min_pq.push(10); min_pq.push(2);
    std::cout << "Min Top: " << min_pq.top() << "\n"; // Output: 2

    // 2. Custom Comparator initialization
    std::priority_queue<int, std::vector<int>, CustomCompare> custom_pq;
    custom_pq.push(5); custom_pq.push(1);
    std::cout << "Custom Top: " << custom_pq.top() << "\n"; // Output: 1
}
